select json_build_object('public_tables',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),'rls_missing',(select json_agg(c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity),'security_definers',(select json_agg(n.nspname||'.'||p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','body_private') and p.prosecdef),'unsafe_paths',(select json_agg(n.nspname||'.'||p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','body_private') and p.prokind='f' and not coalesce(p.proconfig @> array['search_path=""'],false)));
select p.proname,p.prosecdef,p.proconfig,has_function_privilege('anon',p.oid,'execute') as anon,has_function_privilege('authenticated',p.oid,'execute') as authenticated,has_function_privilege('service_role',p.oid,'execute') as service_role from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' order by p.proname;
select tablename,policyname,cmd,roles,qual,with_check from pg_policies where schemaname='public' order by tablename,policyname;
select tablename,indexname,indexdef from pg_indexes where schemaname='public' and tablename in('program_assignments','workout_sessions','workout_sets','program_schedule_decisions','favorite_workouts');
select conrelid::regclass as source,conname,pg_get_constraintdef(oid) from pg_constraint where contype='f' and confrelid='public.workout_sessions'::regclass;
